Do not provide any other text or markdown fences.

Here is the problem description:
<description>
Sometimes one has to spell email addresses over the phone. Then one usually pronounces a dot as dot, an at sign as at. As a result, we get something like vasyaatgmaildotcom. Your task is to transform it into a proper email address (vasya@gmail.com). It is known that a proper email address contains only such symbols as . @ and lower-case Latin letters, doesn't start with and doesn't end with a dot. Also, a proper email address doesn't start with and doesn't end with an at sign. Moreover, an email address contains exactly one such symbol as @, yet may contain any number (possible, zero) of dots. You have to carry out a series of replacements so that the length of the result was as short as possible and it was a proper email address. If the lengths are equal, you should print the lexicographically minimal result. Overall, two variants of replacement are possible: dot can be replaced by a dot, at can be replaced by an at. 
</description>

Here is the input specification:
<input_spec>
The first line contains the email address description. It is guaranteed that that is a proper email address with all the dots replaced by dot an the at signs replaced by at. The line is not empty and its length does not exceed 100 symbols.
</input_spec>


Here are sample inputs:
<sample_inputs>
<input>
vasyaatgmaildotcom
</input>
<input>
dotdotdotatdotdotat
</input>
<input>
aatt
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include<new>
#include<map>
#include<set>
#include<list>
#include<queue>
#include<cmath>
#include<vector>
#include<cstdio>
#include<cstdlib>
#include<cstring>
#include<utility>
#include<iostream>
#include<algorithm>
using namespace std;

string a, b;

int main() {
    cin >> a;

    // We need to find exactly one '@' and any number of '.' to replace
    // The approach: try all possible positions for '@' and '.' replacements
    // to get the shortest valid email address

    int n = a.size();
    vector<pair<int, int>> at_positions; // positions where "at" occurs

    // Find all "at" occurrences
    for (int i = 0; i < n - 1; i++) {
        if (a[i] == 'a' && a[i+1] == 't') {
            at_positions.push_back({i, i+1});
        }
    }

    // Find all "dot" occurrences
    vector<pair<int, int>> dot_positions;
    for (int i = 0; i < n - 2; i++) {
        if (a[i] == 'd' && a[i+1] == 'o' && a[i+2] == 't') {
            dot_positions.push_back({i, i+2});
        }
    }

    string best_result = "";

    // Try each "at" as the single @ in the email
    for (auto& at_pos : at_positions) {
        int at_idx = at_pos.first;

        // Build the email address with this @ position
        string candidate = "";

        // Process before @
        int prev = 0;
        for (int i = 0; i < at_idx; i++) {
            if (i < prev) continue;

            // Check if this is start of "dot"
            if (i <= n-3 && a[i] == 'd' && a[i+1] == 'o' && a[i+2] == 't') {
                candidate += '.';
                prev = i + 2;
                i = i + 2;
            } else {
                candidate += a[i];
            }
        }

        // Add the @
        candidate += '@';

        // Process after @
        prev = at_idx + 2;
        for (int i = at_idx + 2; i < n; i++) {
            if (i < prev) continue;

            // Check if this is start of "dot"
            if (i <= n-3 && a[i] == 'd' && a[i+1] == 'o' && a[i+2] == 't') {
                candidate += '.';
                prev = i + 2;
                i = i + 2;
            } else {
                candidate += a[i];
            }
        }

        // Validate the candidate
        bool valid = true;

        // Check length
        if (candidate.empty()) valid = false;

        // Check starts and ends with . or @
        if (valid && (candidate[0] == '.' || candidate[0] == '@' || 
                      candidate.back() == '.' || candidate.back() == '@')) {
            valid = false;
        }

        // Check contains exactly one @
        int at_count = 0;
        for (char c : candidate) {
            if (c == '@') at_count++;
        }
        if (at_count != 1) valid = false;

        // Check only allowed characters
        for (char c : candidate) {
            if (c != '.' && c != '@' && (c < 'a' || c > 'z')) {
                valid = false;
                break;
            }
        }

        // Check no consecutive dots
        for (int i = 0; i < (int)candidate.size() - 1; i++) {
            if (candidate[i] == '.' && candidate[i+1] == '.') {
                valid = false;
                break;
            }
        }

        if (valid) {
            if (best_result.empty() || 
                candidate.size() < best_result.size() || 
                (candidate.size() == best_result.size() && candidate < best_result)) {
                best_result = candidate;
            }
        }
    }

    cout << best_result << endl;
    return 0;
}
</source_code>
